#include <iostream>
#include <vector>
template <template <typename T> class Container, typename T> void process(Container<T>& container) {
  std::cout << "Size: " << container.size() << std::endl;
}
template <typename T> using MyVector = std::vector<T>;
int main() {
  MyVector<int> vec; 
  vec.push_back(10);
  process(vec); // Pass std::vector as the Container template parameter
  return 0;
}
